  "lesson_logic_foundation_02": Lesson(id: "lesson_logic_foundation_02", courseId: "course_logic", skillId: "skill_logic_puzzles", title: "Mulohazani inkor qiliş", titleRu: "Отрицание высказывания", summary: "Guruhdagi hamma odam keldi degan gapni bitta dalil bilan qanday rad etasiz?", summaryRu: "Как одним наблюдением опровергнуть фразу «Все пришли»?", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_foundation_02_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "Guruhdagi hamma odam keldi degan gapni bitta dalil bilan qanday rad etasiz?", contentRu: "Как одним наблюдением опровергнуть фразу «Все пришли»?"), LessonStep(id: "lesson_logic_foundation_02_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "«Hamma keldi» gapining inkori «Kamida bir kişi kelmadi». Bitta kelmagan kişi kifoya.", contentRu: "Отрицание «Все пришли» — «Хотя бы один не пришёл». Достаточно одного отсутствующего."), LessonStep(id: "lesson_logic_foundation_02_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_foundation_02_v2_1", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Barça daftarlar kök» gapining inkori qaysi? A) Heç biri kök emas B) Kamida bittasi kök emas C) Bittasi kök", textRu: "Отрицание «Все тетради синие»: A) ни одна не синяя B) хотя бы одна не синяя C) одна синяя.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.easy, explanation: "Bitta kök bölmagan daftar umumiy da’voni rad etadi.", explanationRu: "Достаточно одной несиней тетради.")), LessonStep(id: "lesson_logic_foundation_02_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_foundation_02_v2_2", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Heç kim keçikmadi» gapini rad eting. A) Kamida bir kişi keçikdi B) Hamma keçikdi C) Hamma vaqtida keldi", textRu: "Опровергните «Никто не опоздал». A) хотя бы один опоздал B) все опоздали C) все пришли вовремя.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.easy, explanation: "Hamma keçikişi şart emas. Bitta holat yetarli.", explanationRu: "Все опаздывать не обязаны. Достаточно одного случая."))], reinforcementExercise: Question(id: "q_lesson_logic_foundation_02_v2_3", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Kamida bitta fayl tayyor» inkori qaysi? A) Hamma fayl tayyor B) Ayrimlari tayyor C) Heç biri tayyor emas", textRu: "Отрицание «Хотя бы один файл готов»: A) все готовы B) некоторые готовы C) ни один не готов.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.easy, explanation: "Bitta ham tayyor bölmasa, dastlabki gap yolğon.", explanationRu: "Если ни один не готов, исходное утверждение ложно.")),
  "lesson_logic_connectives": Lesson(id: "lesson_logic_connectives", courseId: "course_logic", skillId: "skill_logic_puzzles", title: "«Va» hamda «yoki»", titleRu: "«И» и «или»", summary: "Sayohatga daftar va ruçka kerak. Faqat bittasini olganingizda şart bajariladimi?", summaryRu: "Для поездки нужны тетрадь и ручка. Достаточно взять одно?", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_connectives_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "Sayohatga daftar va ruçka kerak. Faqat bittasini olganingizda şart bajariladimi?", contentRu: "Для поездки нужны тетрадь и ручка. Достаточно взять одно?"), LessonStep(id: "lesson_logic_connectives_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "«A va B» uçun ikkalasi ham kerak. Darsdagi «A yoki B» kamida bittasini anglatadi. Ikki javob rost bölişi ham mumkin.", contentRu: "Для «A и B» нужны оба условия. Здесь «A или B» означает хотя бы одно и допускает оба.", media: LessonMedia(kind: LessonMediaKind.image, language: LessonMediaLanguage.uz, id: "logic_gates", title: "Mantiqiy boğlovçilar", titleRu: "Связки", source: "/lesson-media/logic/gates.png", alt: "«A va B» uçun ikkalasi ham kerak. Darsdagi «A yoki B» kamida bittasini anglatadi. Ikki javob rost bölişi ham mumkin.", altRu: "Для «A и B» нужны оба условия. Здесь «A или B» означает хотя бы одно и допускает оба.")), LessonStep(id: "lesson_logic_connectives_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_connectives_v2_1", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Ruçka bor, daftar yöq. «Daftar va ruçka bor» qaysi? A) Rost B) Yolğon C) Bilib bölmaydi", textRu: "Ручка есть, тетради нет. «Есть и тетрадь, и ручка» — A) истинно B) ложно C) неизвестно.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.easy, explanation: "«Va»da bitta yolğon şart butun gapni yolğon qiladi.", explanationRu: "Для «и» ложность одного условия делает ложным всё высказывание.")), LessonStep(id: "lesson_logic_connectives_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_connectives_v2_2", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Ham kitob, ham jurnal bor. «Kamida bittasi bor» qaysi? A) Yolğon B) Noma’lum C) Rost", textRu: "Есть и книга, и журнал. «Есть хотя бы одно» — A) ложно B) неизвестно C) истинно.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.easy, explanation: "Ikkita mavjud narsa ham kamida bitta degani.", explanationRu: "Два предмета удовлетворяют условию «хотя бы один»."))], reinforcementExercise: Question(id: "q_lesson_logic_connectives_v2_3", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Faylni USB yoki email orqali yuboriş mumkin, ikkalasi ham ruxsat. Email yetadimi? A) Ha B) Yöq, ikkalasi şart C) Faqat USB", textRu: "Разрешены USB и email, достаточно любого. Хватит ли email? A) да B) нет, нужны оба C) только USB.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.easy, explanation: "Email berilgan ikki imkoniyatdan biri.", explanationRu: "Email — один из двух разрешённых способов.")),
