  "lesson_logic_reverse": Lesson(id: "lesson_logic_reverse", courseId: "course_logic", skillId: "skill_logic_puzzles", title: "Teskari xulosani tekşiriş", titleRu: "Проверка обратного вывода", summary: "Agar avtobus yölga çiqsa, çiroği yonadi. Çiroq yonmagan. Avtobus yölga çiqqanmi?", summaryRu: "Если автобус выехал, горит его фонарь. Фонарь не горит. Автобус выехал?", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_reverse_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "Agar avtobus yölga çiqsa, çiroği yonadi. Çiroq yonmagan. Avtobus yölga çiqqanmi?", contentRu: "Если автобус выехал, горит его фонарь. Фонарь не горит. Автобус выехал?"), LessonStep(id: "lesson_logic_reverse_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "Agar A ⇒ B va B yolğon bölsa, A ham yolğon. A yolğon bölsa, B haqida umumiy xulosa yöq.", contentRu: "Из A ⇒ B и отсутствия B следует отсутствие A. Из отсутствия A вывод о B не следует.", media: LessonMedia(kind: LessonMediaKind.image, language: LessonMediaLanguage.uz, id: "logic_counterexample", title: "Xulosa va qarşi misol", titleRu: "Вывод и контрпример", source: "/lesson-media/logic/counterexample.png", alt: "Agar A ⇒ B va B yolğon bölsa, A ham yolğon. A yolğon bölsa, B haqida umumiy xulosa yöq.", altRu: "Из A ⇒ B и отсутствия B следует отсутствие A. Из отсутствия A вывод о B не следует.")), LessonStep(id: "lesson_logic_reverse_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_reverse_v2_1", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Karta işlasa, panel yaşil yonadi. Panel yaşil emas. A) Karta işlaydi B) İşlamaydi C) Noma’lum", textRu: "Рабочая карта включает зелёный индикатор. Индикатор не зелёный. A) карта работает B) не работает C) неизвестно.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.medium, explanation: "Karta işlaganida panel yaşil bölar edi.", explanationRu: "При рабочей карте индикатор был бы зелёным.")), LessonStep(id: "lesson_logic_reverse_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_reverse_v2_2", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Agar kutubxona oçiq bölsa, çiroği yonadi». U yopiq. Çiroq qanday? A) Öçgan B) Yonib turibdi C) Noma’lum", textRu: "Если библиотека открыта, горит свет. Она закрыта. Что со светом? A) погашен B) горит C) неизвестно.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.medium, explanation: "Yopiq binoda ham navbatçi çiroqni yoqib qöyişi mumkin.", explanationRu: "Свет мог оставить дежурный."))], reinforcementExercise: Question(id: "q_lesson_logic_reverse_v2_3", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Agar fayl yuklansa, röyxatda körinadi. Röyxatda yöq. A) Yuklanmagan B) Yuklangan C) Xulosa yöq", textRu: "Загруженный файл есть в списке. Его нет в списке. A) не загружен B) загружен C) вывода нет.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.medium, explanation: "Qoidaga zid holatni A ni inkor qilib yeçasiz.", explanationRu: "По правилу отсутствие результата исключает исходное условие.")),
  "lesson_logic_counterexample": Lesson(id: "lesson_logic_counterexample", courseId: "course_logic", skillId: "skill_logic_puzzles", title: "Qarşi misol", titleRu: "Контрпример", summary: "«Barça juft sonlar 4 ga bölinadi» degan gapni tekşiring.", summaryRu: "Проверьте утверждение «Все чётные числа делятся на 4».", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_counterexample_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "«Barça juft sonlar 4 ga bölinadi» degan gapni tekşiring.", contentRu: "Проверьте утверждение «Все чётные числа делятся на 4»."), LessonStep(id: "lesson_logic_counterexample_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "6 juft, lekin 4 ga bölinmaydi. U da’voning doirasiga kiradi va aytilgan xususiyatga ega emas.", contentRu: "6 — чётное, но на 4 не делится. Оно входит в область утверждения и нарушает свойство."), LessonStep(id: "lesson_logic_counterexample_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_counterexample_v2_1", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Barça törtburçaklar kvadrat» gapiga qarşi misol. A) Uçburçak B) Kvadrat C) Tomonlari 2 va 5 töğri törtburçak", textRu: "Контрпример к «Все четырёхугольники — квадраты»: A) треугольник B) квадрат C) прямоугольник 2 на 5.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.medium, explanation: "C törtburçak, tomonlari teng emas.", explanationRu: "C — четырёхугольник с неравными сторонами.")), LessonStep(id: "lesson_logic_counterexample_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_counterexample_v2_2", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Barça juft sonlar 10 dan katta» gapiga qarşi misol. A) 6 B) 11 C) 12", textRu: "Контрпример к «Все чётные числа больше 10»: A) 6 B) 11 C) 12.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.medium, explanation: "6 juft va 10 dan kiçik.", explanationRu: "6 — чётное и меньше 10."))], reinforcementExercise: Question(id: "q_lesson_logic_counterexample_v2_3", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Barça A lar B» ga qarşi misol nimaga ega? A) Faqat B B) A, lekin B emas C) A va B", textRu: "Каким должен быть контрпример к «Все A — B»? A) только B B) A, но не B C) A и B.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.medium, explanation: "Misol da’voning A doirasida bölişi kerak.", explanationRu: "Пример должен относиться к области A.")),
  "lesson_logic_argument_map": Lesson(id: "lesson_logic_argument_map", courseId: "course_logic", skillId: "skill_logic_puzzles", title: "Dalil xaritasi", titleRu: "Карта аргумента", summary: "Xabarda xulosani toping va uni qaysi ikki gap birga asoslaşini köring.", summaryRu: "Найдите вывод в сообщении и два суждения, которые вместе его поддерживают.", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_argument_map_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "Xabarda xulosani toping va uni qaysi ikki gap birga asoslaşini köring.", contentRu: "Найдите вывод в сообщении и два суждения, которые вместе его поддерживают."), LessonStep(id: "lesson_logic_argument_map_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "Barça olma meva. Bu olma. Ikkala dalil birga «bu meva» xulosasini beradi.", contentRu: "Все яблоки — фрукты. Это яблоко. Вместе эти посылки дают вывод «Это фрукт».", media: LessonMedia(kind: LessonMediaKind.image, language: LessonMediaLanguage.uz, id: "logic_argument", title: "Dalil va da’vo", titleRu: "Аргумент и данные", source: "/lesson-media/logic/argument.png", alt: "Barça olma meva. Bu olma. Ikkala dalil birga «bu meva» xulosasini beradi.", altRu: "Все яблоки — фрукты. Это яблоко. Вместе эти посылки дают вывод «Это фрукт».")), LessonStep(id: "lesson_logic_argument_map_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_argument_map_v2_1", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Barça musobaqa iştirokçilari röyxatda. Zebo musobaqada qatnaşadi. Xulosa? A) Zebo röyxatda B) Zebo ğolib C) Hamma Zebo bilan bir guruhda", textRu: "Все участники в списке. Зебо участвует. Вывод: A) Зебо в списке B) Зебо победит C) все в одной группе с Зебо.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.medium, explanation: "Ikki dalil röyxatga oid, ğolibga oid dalil yöq.", explanationRu: "Общие сведения и частный случай дают вывод о списке.")), LessonStep(id: "lesson_logic_argument_map_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_argument_map_v2_2", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Sumkada uç kitob, men bittasini oldim, demak ikkita qoldi.» Xulosa qaysi? A) Uç kitob bor edi B) Bittasini oldim C) Ikkita qoldi", textRu: "«В сумке было три книги, я взял одну, значит осталось две». Вывод: A) было три B) взял одну C) осталось две.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.medium, explanation: "C avvalgi ikkita gap asosida kelib çiqadi.", explanationRu: "C следует из первых двух суждений."))], reinforcementExercise: Question(id: "q_lesson_logic_argument_map_v2_3", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "«Bu A. Barça A lar B» ni nima yakunlaydi? A) Bu A emas B) Bu B C) Hamma B lar A", textRu: "«Это A. Все A — B». Вывод: A) это не A B) это B C) все B — A.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.medium, explanation: "A ga tegişli obyektga umumiy qoida tatbiq etiladi.", explanationRu: "Общее правило применяется к объекту A.")),
  "lesson_logic_evidence": Lesson(id: "lesson_logic_evidence", courseId: "course_logic", skillId: "skill_logic_puzzles", title: "Dalilning çegarasi", titleRu: "Граница доказательства", summary: "«Tekşirilgan ikki sinfda usul foyda berdi» degan xabarni öqing. Butun maktab haqida nima deyiş mumkin?", summaryRu: "«В двух проверенных классах метод помог». Что можно сказать обо всей школе?", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_evidence_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "«Tekşirilgan ikki sinfda usul foyda berdi» degan xabarni öqing. Butun maktab haqida nima deyiş mumkin?", contentRu: "«В двух проверенных классах метод помог». Что можно сказать обо всей школе?"), LessonStep(id: "lesson_logic_evidence_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "Ma’lumot ikki sinfni qamrab oladi. Boşqa sinflarga xulosa yoyişdan oldin ularni ham tekşiramiz.", contentRu: "Данные относятся к двум классам. Для вывода о других классах нужны их данные."), LessonStep(id: "lesson_logic_evidence_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_evidence_v2_1", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Uç avtobusdan biri keçikdi. Nima aniq? A) Hamma avtobus keçikadi B) Uçta kuzatuvda bitta keçikiş bor C) Ertaga ham bittasi keçikadi", textRu: "Один из трёх наблюдаемых автобусов опоздал. Что установлено? A) все опаздывают B) в трёх наблюдениях одно опоздание C) завтра один опоздает.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.medium, explanation: "B da’vo kuzatuvlar doirasida qoladi.", explanationRu: "B остаётся в пределах наблюдений.")), LessonStep(id: "lesson_logic_evidence_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_evidence_v2_2", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Xabar «barça içimliklar sovuq» deydi. Eng mos tekşiruv? A) Xabarning layklarini sanaş B) Bitta rasmni köriş C) Har bir içimlik haroratini ölçaş", textRu: "«Все напитки холодные». Как это проверить? A) подсчитать лайки B) посмотреть одно фото C) измерить температуру каждого.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.medium, explanation: "Ölçov aynan da’vodagi haroratni va töliq doirani tekşiradi.", explanationRu: "Измерение проверяет требуемое свойство у всех объектов."))], reinforcementExercise: Question(id: "q_lesson_logic_evidence_v2_3", courseId: "course_logic", skillId: "skill_logic_puzzles", text: "Bitta maktabdan olingan natija haqida qaysi gap ehtiyotkor? A) Şu maktabda kuzatildi B) Butun şaharda rost C) Keyingi yilda ham aynan şunday", textRu: "Как осторожно описать данные одной школы? A) наблюдали в этой школе B) так во всём городе C) так же будет в следующем году.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.medium, explanation: "Dalilning joy va vaqt doirasini saqlang.", explanationRu: "Сохраняйте границы данных по месту и времени.")),
  "lesson_logic_patterns_01": Lesson(id: "lesson_logic_patterns_01", courseId: "course_logic", skillId: "skill_logic_patterns", title: "Ketma-ketlikdagi özgariş", titleRu: "Изменения в последовательности", summary: "Bir daftar 3 ming, ikkitasi 6 ming, uçtasi 9 ming. Narxdagi har bir qadamni yozing.", summaryRu: "Одна тетрадь стоит 3 тысячи, две — 6, три — 9. Как меняется стоимость?", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_patterns_01_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "Bir daftar 3 ming, ikkitasi 6 ming, uçtasi 9 ming. Narxdagi har bir qadamni yozing.", contentRu: "Одна тетрадь стоит 3 тысячи, две — 6, три — 9. Как меняется стоимость?"), LessonStep(id: "lesson_logic_patterns_01_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "3 → 6 → 9. Har safar +3. Keyingi qiymat 12. Qoidani ayting, söng yangi hadni hisoblang.", contentRu: "3 → 6 → 9. Каждый раз +3. Далее 12. Сначала назовите правило, затем считайте.", media: LessonMedia(kind: LessonMediaKind.image, language: LessonMediaLanguage.uz, id: "logic_patterns", title: "Qonuniyatlar", titleRu: "Закономерности", source: "/lesson-media/logic/patterns.png", alt: "3 → 6 → 9. Har safar +3. Keyingi qiymat 12. Qoidani ayting, söng yangi hadni hisoblang.", altRu: "3 → 6 → 9. Каждый раз +3. Далее 12. Сначала назовите правило, затем считайте.")), LessonStep(id: "lesson_logic_patterns_01_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_patterns_01_v2_1", courseId: "course_logic", skillId: "skill_logic_patterns", text: "Qoida har qadamda +4. 2, 6, 10, … Keyingi? A) 12 B) 14 C) 16", textRu: "Правило +4. 2, 6, 10, … Что дальше? A) 12 B) 14 C) 16.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.medium, explanation: "10 + 4 = 14.", explanationRu: "10 + 4 = 14.")), LessonStep(id: "lesson_logic_patterns_01_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_patterns_01_v2_2", courseId: "course_logic", skillId: "skill_logic_patterns", text: "Qoida har qadamda ×2. 3, 6, 12, … Keyingi? A) 15 B) 18 C) 24", textRu: "Правило ×2. 3, 6, 12, … Что дальше? A) 15 B) 18 C) 24.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.medium, explanation: "12 ni ikki baravar qilsak, 24 böladi.", explanationRu: "Удвоение 12 даёт 24."))], reinforcementExercise: Question(id: "q_lesson_logic_patterns_01_v2_3", courseId: "course_logic", skillId: "skill_logic_patterns", text: "10, 7, 4. Har gal bir xil farq. Qaysi qoida? A) −3 B) +3 C) ÷3", textRu: "10, 7, 4. Разность постоянна. Какое правило? A) −3 B) +3 C) ÷3.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.medium, explanation: "Har ikki oraliqda ham uç kamaygan.", explanationRu: "На обоих переходах число уменьшилось на три.")),
  "lesson_logic_rules": Lesson(id: "lesson_logic_rules", courseId: "course_logic", skillId: "skill_logic_patterns", title: "Bir neçta qoida", titleRu: "Несколько возможных правил", summary: "Qisqa ketma-ketlikka ikki xil qoida ham mos kelişi mumkin. Ularni qaysi yangi had ajratadi?", summaryRu: "К короткой последовательности могут подходить два правила. Какой новый член их различит?", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_rules_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "Qisqa ketma-ketlikka ikki xil qoida ham mos kelişi mumkin. Ularni qaysi yangi had ajratadi?", contentRu: "К короткой последовательности могут подходить два правила. Какой новый член их различит?"), LessonStep(id: "lesson_logic_rules_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "2, 4, 6 dan söng «har doim +2» 8 ni beradi, «2,4,6 takrorlanadi» 2 ni beradi. Törtinçi had qoidalarni ajratadi.", contentRu: "После 2, 4, 6 правило «всегда +2» даёт 8, а повтор «2, 4, 6» даёт 2. Четвёртый член различает правила."), LessonStep(id: "lesson_logic_rules_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_rules_v2_1", courseId: "course_logic", skillId: "skill_logic_patterns", text: "2,4,6,2 berildi. Mos qoida? A) +2 B) 2,4,6 takrori C) ×2", textRu: "Дано 2, 4, 6, 2. Какое правило подходит? A) +2 B) повтор 2, 4, 6 C) ×2.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.medium, explanation: "+2 törtinçi joyda 8 beradi.", explanationRu: "Правило +2 дало бы четвёртым числом 8.")), LessonStep(id: "lesson_logic_rules_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_rules_v2_2", courseId: "course_logic", skillId: "skill_logic_patterns", text: "1,2,4. «×2» va «+1,+2,+1,+2…» farazlari. Keyingi had 8 bölsa, qaysi biri mos? A) ×2 B) Ikkinçi C) Ikkalasi", textRu: "1, 2, 4. Гипотезы: «×2» и «+1, +2, +1, +2…». Следующий член 8. Что подходит? A) ×2 B) второе C) оба.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.medium, explanation: "Ikkinçi qoida 4 dan söng 5 ni beradi.", explanationRu: "Второе правило дало бы 5."))], reinforcementExercise: Question(id: "q_lesson_logic_rules_v2_3", courseId: "course_logic", skillId: "skill_logic_patterns", text: "Ikki faraz bir xil navbatdagi natijani beradi. Eng yaxşi qadam? A) Ilk farazni tanlaş B) Ikkalasi ham isbotlangan deyiş C) Başorat farq qiladigan navbatni tekşiriş", textRu: "Две гипотезы дают одинаковый ближайший результат. Как их различить? A) выбрать первую B) принять обе как доказанные C) проверить шаг, где прогнозы расходятся.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.medium, explanation: "Farqlovçi ma’lumot taxminlarni sinaş imkonini beradi.", explanationRu: "Различающее наблюдение позволяет проверить гипотезы.")),
  "lesson_logic_constraints": Lesson(id: "lesson_logic_constraints", courseId: "course_logic", skillId: "skill_logic_patterns", title: "Çeklovli jadval", titleRu: "Расписание с ограничениями", summary: "Uçta tadbir bir vaqtda bölmasligi kerak. Qaysi örinlardan boşlaş qulay?", summaryRu: "Три события не могут иметь одно время. С чего начать расстановку?", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_constraints_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "Uçta tadbir bir vaqtda bölmasligi kerak. Qaysi örinlardan boşlaş qulay?", contentRu: "Три события не могут иметь одно время. С чего начать расстановку?"), LessonStep(id: "lesson_logic_constraints_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "A B dan oldin, C oxirida. Avval C ni joylang. Qolgan örinlarda A, B böladi.", contentRu: "A раньше B, C последний. Сначала поставьте C. Оставшиеся места займут A и B.", media: LessonMedia(kind: LessonMediaKind.image, language: LessonMediaLanguage.uz, id: "logic_schedule", title: "Tatbiq", titleRu: "Применение", source: "/lesson-media/logic/schedule.png", alt: "A B dan oldin, C oxirida. Avval C ni joylang. Qolgan örinlarda A, B böladi.", altRu: "A раньше B, C последний. Сначала поставьте C. Оставшиеся места займут A и B.")), LessonStep(id: "lesson_logic_constraints_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_constraints_v2_1", courseId: "course_logic", skillId: "skill_logic_patterns", text: "A B dan oldin, C oxirida. Mos jadval? A) B,A,C B) A,B,C C) C,A,B", textRu: "A раньше B, C последний. Подходящий порядок: A) B, A, C B) A, B, C C) C, A, B.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.medium, explanation: "Har ikki şart birga bajarilişi kerak.", explanationRu: "Оба ограничения должны выполняться одновременно.")), LessonStep(id: "lesson_logic_constraints_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_constraints_v2_2", courseId: "course_logic", skillId: "skill_logic_patterns", text: "D birinçi emas va F oxirida. Boşqa şart yöq. Mos jadval? A) E,D,F B) D,E,F C) E,F,D", textRu: "D не первый, F последний. Подходящий порядок: A) E, D, F B) D, E, F C) E, F, D.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.medium, explanation: "D ikkinçi, F uçinçi. Ikkala şart bajarildi.", explanationRu: "D второй, F третий. Оба условия выполнены."))], reinforcementExercise: Question(id: "q_lesson_logic_constraints_v2_3", courseId: "course_logic", skillId: "skill_logic_patterns", text: "A dan keyin darhol B va C A dan oldin. Mos jadval? A) A,C,B B) A,B,C C) C,A,B", textRu: "B сразу после A, C раньше A. Порядок: A) A, C, B B) A, B, C C) C, A, B.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.medium, explanation: "A va B yonma-yon, C esa oldinda.", explanationRu: "A и B соседние, C идёт раньше.")),
  "lesson_logic_capstone": Lesson(id: "lesson_logic_capstone", courseId: "course_logic", skillId: "skill_logic_patterns", title: "Yakuniy mantiq vaziyati", titleRu: "Итоговая логическая задача", summary: "Maktab xabarida «Ruxsatli jamoalar zalga kiradi, binobarin zaldagi hamma ruxsatli» deyildi. Qaysi qadam dalilsiz?", summaryRu: "«Группы с разрешением входят в зал, значит у всех в зале есть разрешение». Где необоснованный шаг?", estimatedMinutes: 7, steps: [LessonStep(id: "lesson_logic_capstone_v2_step_1", stepNumber: 1, type: LessonStepType.concept, title: "Vaziyat", titleRu: "Ситуация", content: "Maktab xabarida «Ruxsatli jamoalar zalga kiradi, binobarin zaldagi hamma ruxsatli» deyildi. Qaysi qadam dalilsiz?", contentRu: "«Группы с разрешением входят в зал, значит у всех в зале есть разрешение». Где необоснованный шаг?"), LessonStep(id: "lesson_logic_capstone_v2_step_2", stepNumber: 2, type: LessonStepType.visualExample, title: "Işlangan misol", titleRu: "Разбор примера", content: "Ruxsat zalga kiriş uçun yetarli. Ammo ruxsatsiz tomoşabin ham zalda bölsa, «zaldagi hamma ruxsatli» xulosasi yolğon.", contentRu: "Разрешения достаточно для входа. Зритель без разрешения в зале опровергает вывод «У всех в зале есть разрешение»."), LessonStep(id: "lesson_logic_capstone_v2_step_3", stepNumber: 3, type: LessonStepType.interactiveQuestion, title: "Birinçi uriniş", titleRu: "Первая попытка", content: "Variantni tanlang.", contentRu: "Выберите вариант.", interactiveQuestion: Question(id: "q_lesson_logic_capstone_v2_1", courseId: "course_logic", skillId: "skill_logic_patterns", text: "Qoidada «Agar maşq bitgan bölsa, belgi çiqadi». Belgi yöq. Xulosa? A) Maşq bitmagan B) Maşq bitgan C) Noma’lum", textRu: "«Если упражнение закончено, появляется отметка». Отметки нет. A) упражнение не закончено B) закончено C) неизвестно.", options: ["A", "B", "C"], correctIndex: 0, difficulty: QuestionDifficulty.medium, explanation: "A bajarilganda B çiqardi, şuning uçun A bajarilmagan.", explanationRu: "При выполнении A появился бы B, поэтому A не выполнено.")), LessonStep(id: "lesson_logic_capstone_v2_step_4", stepNumber: 4, type: LessonStepType.interactiveQuestion, title: "Yangi vaziyat", titleRu: "Новая ситуация", content: "Qoidani yangi misolga qöllang.", contentRu: "Примените правило в новом примере.", interactiveQuestion: Question(id: "q_lesson_logic_capstone_v2_2", courseId: "course_logic", skillId: "skill_logic_patterns", text: "«Barça uçraşuv ertalab» xabarini nima rad etadi? A) Bir ertalabgi uçraşuv B) Uçta ertalabgi uçraşuv C) Bir keçki uçraşuv", textRu: "Что опровергает «Все встречи утром»? A) одна утренняя встреча B) три утренних встречи C) одна вечерняя встреча.", options: ["A", "B", "C"], correctIndex: 2, difficulty: QuestionDifficulty.medium, explanation: "Bitta keçki uçraşuv ham umumiy da’voni rad etadi.", explanationRu: "Одной вечерней встречи достаточно для опровержения."))], reinforcementExercise: Question(id: "q_lesson_logic_capstone_v2_3", courseId: "course_logic", skillId: "skill_logic_patterns", text: "Ikki jamoadan söraldi, ikkalasi yangi jadvalni yoqtirdi. Isbotlangan xulosa? A) Hamma yoqtirdi B) Söralgan ikki jamoa yoqtirdi C) Heç kim qarşi emas", textRu: "Опросили две команды, обе одобрили график. Установлено: A) всем нравится B) двум опрошенным нравится C) никто не против.", options: ["A", "B", "C"], correctIndex: 1, difficulty: QuestionDifficulty.medium, explanation: "Dalil faqat ikki jamoani qamragan.", explanationRu: "Данные охватывают только две команды.")),
};

